  content = EXCLUDED.content,
  category = EXCLUDED.category,
  updated_at = NOW();

INSERT INTO law_sections (id, book_id, section_number, content, category, is_custom) VALUES
  ('const-10', 'const', '๑๐', 'พระมหากษัตริย์ทรงเลือกและทรงแต่งตั้งผู้ทรงคุณวุฒิเป็นประธานองคมนตรีคนหนึ่งและองคมนตรีอื่นอีกไม่เกินสิบแปดคนประกอบเป็นคณะองคมนตรี
คณะองคมนตรีมีหน้าที่ถวายความเห็นต่อพระมหากษัตริย์ในพระราชกรณียกิจทั้งปวงที่พระมหากษัตริย์ทรงปรึกษา และมีหน้าที่อื่นตามที่บัญญัติไว้ในรัฐธรรมนูญ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-11', 'const', '๑๑', 'การเลือกและแต่งตั้งองคมนตรีหรือการให้องคมนตรีพ้นจากตำแหน่ง ให้เป็นไปตามพระราชอัธยาศัย
ให้ประธานรัฐสภาเป็นผู้ลงนามรับสนองพระบรมราชโองการแต่งตั้งประธานองคมนตรีหรือให้ประธานองคมนตรีพ้นจากตำแหน่ง
ให้ประธานองคมนตรีเป็นผู้ลงนามรับสนองพระบรมราชโองการแต่งตั้งองคมนตรีอื่นหรือให้องคมนตรีอื่นพ้นจากตำแหน่ง', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-12', 'const', '๑๒', 'องคมนตรีต้องไม่เป็นสมาชิกสภาผู้แทนราษฎร สมาชิกวุฒิสภา หรือดำรงตำแหน่งทางการเมืองอื่น ตุลาการศาลรัฐธรรมนูญ ผู้ดำรงตำแหน่งในองค์กรอิสระ พนักงานรัฐวิสาหกิจ เจ้าหน้าที่อื่นของรัฐ หรือสมาชิกหรือเจ้าหน้าที่ของพรรคการเมือง หรือข้าราชการเว้นแต่การเป็นข้าราชการในพระองค์ในตำแหน่งองคมนตรี และต้องไม่แสดงการฝักใฝ่ในพรรคการเมืองใด ๆ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-13', 'const', '๑๓', 'ก่อนเข้ารับหน้าที่ องคมนตรีต้องถวายสัตย์ปฏิญาณต่อพระมหากษัตริย์ด้วยถ้อยคำ ดังต่อไปนี้
“ข้าพระพุทธเจ้า (ชื่อผู้ปฏิญาณ) ขอถวายสัตย์ปฏิญาณว่า ข้าพระพุทธเจ้าจะจงรักภักดีต่อพระมหากษัตริย์ และจะปฏิบัติหน้าที่ด้วยความซื่อสัตย์สุจริต เพื่อประโยชน์ของประเทศและประชาชน ทั้งจะรักษาไว้และปฏิบัติตามซึ่งรัฐธรรมนูญแห่งราชอาณาจักรไทยทุกประการ”', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-14', 'const', '๑๔', 'องคมนตรีพ้นจากตำแหน่งเมื่อตาย ลาออก หรือมีพระบรมราชโองการให้พ้นจากตำแหน่ง', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-15', 'const', '๑๕', 'การแต่งตั้งและการให้ข้าราชการในพระองค์พ้นจากตำแหน่ง ให้เป็นไปตามพระราชอัธยาศัย
การจัดระเบียบราชการและการบริหารงานบุคคลของราชการในพระองค์ ให้เป็นไปตามพระราชอัธยาศัยตามที่บัญญัติไว้ในพระราชกฤษฎีกา', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-16', 'const', '๑๖', 'ในเมื่อพระมหากษัตริย์จะไม่ประทับอยู่ในราชอาณาจักร หรือจะทรงบริหารพระราชภาระไม่ได้ด้วยเหตุใดก็ตาม จะทรงแต่งตั้งบุคคลคนหนึ่งหรือหลายคนเป็นคณะขึ้น ให้เป็นผู้สำเร็จราชการแทนพระองค์หรือไม่ก็ได้ และในกรณีที่ทรงแต่งตั้งผู้สำเร็จราชการแทนพระองค์ให้ประธานรัฐสภาเป็นผู้ลงนามรับสนองพระบรมราชโองการ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-17', 'const', '๑๗', 'ในกรณีที่พระมหากษัตริย์มิได้ทรงแต่งตั้งผู้สำเร็จราชการแทนพระองค์ตามมาตรา ๑๖ หรือในกรณีที่พระมหากษัตริย์ไม่สามารถทรงแต่งตั้งผู้สำเร็จราชการแทนพระองค์เพราะยังไม่ทรงบรรลุนิติภาวะหรือเพราะเหตุอื่น แต่ต่อมาคณะองคมนตรีพิจารณาเห็นว่ามีความจำเป็นสมควรแต่งตั้งผู้สำเร็จราชการแทนพระองค์และไม่อาจกราบบังคมทูลให้ทรงแต่งตั้งได้ทันการ ให้คณะองคมนตรีเสนอชื่อบุคคลคนหนึ่งหรือหลายคนเป็นคณะ ตามลำดับที่โปรดเกล้าโปรดกระหม่อมกำหนดไว้ก่อนแล้วให้เป็นผู้สำเร็จราชการแทนพระองค์ แล้วแจ้งประธานรัฐสภาเพื่อประกาศในพระปรมาภิไธยพระมหากษัตริย์ แต่งตั้งผู้นั้นขึ้นเป็นผู้สำเร็จราชการแทนพระองค์', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-18', 'const', '๑๘', 'ในระหว่างที่ไม่มีผู้สำเร็จราชการแทนพระองค์ตามมาตรา ๑๗ ให้ประธานองคมนตรีเป็นผู้สำเร็จราชการแทนพระองค์เป็นการชั่วคราวไปพลางก่อน
ในกรณีที่ผู้สำเร็จราชการแทนพระองค์ซึ่งได้รับการแต่งตั้งตามมาตรา ๑๖ หรือมาตรา ๑๗ ไม่สามารถปฏิบัติหน้าที่ได้ ให้ประธานองคมนตรีทำหน้าที่ผู้สำเร็จราชการแทนพระองค์เป็นการชั่วคราวไปพลางก่อน
ในระหว่างที่ประธานองคมนตรีเป็นผู้สำเร็จราชการแทนพระองค์ตามวรรคหนึ่ง หรือในระหว่างที่ประธานองคมนตรีทำหน้าที่ผู้สำเร็จราชการแทนพระองค์ตามวรรคสอง ประธานองคมนตรีจะปฏิบัติหน้าที่ในฐานะเป็นประธานองคมนตรีมิได้ ในกรณีเช่นว่านี้ ให้คณะองคมนตรีเลือกองคมนตรีคนหนึ่งขึ้นทำหน้าที่ประธานองคมนตรีเป็นการชั่วคราวไปพลางก่อน', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-19', 'const', '๑๙', 'ก่อนเข้ารับหน้าที่ ผู้สำเร็จราชการแทนพระองค์ซึ่งได้รับการแต่งตั้งตามมาตรา ๑๖ หรือมาตรา ๑๗ ต้องปฏิญาณตนในที่ประชุมรัฐสภาด้วยถ้อยคำ ดังต่อไปนี้
“ข้าพเจ้า (ชื่อผู้ปฏิญาณ) ขอปฏิญาณว่า ข้าพเจ้าจะจงรักภักดีต่อพระมหากษัตริย์ (พระปรมาภิไธย) และจะปฏิบัติหน้าที่ด้วยความซื่อสัตย์สุจริต เพื่อประโยชน์ของประเทศและประชาชน ทั้งจะรักษาไว้และปฏิบัติตามซึ่งรัฐธรรมนูญแห่งราชอาณาจักรไทยทุกประการ”
ผู้สำเร็จราชการแทนพระองค์ซึ่งเคยได้รับการแต่งตั้งและปฏิญาณตนมาแล้ว ไม่ต้องปฏิญาณตนอีก', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-20', 'const', '๒๐', 'ภายใต้บังคับมาตรา ๒๑ การสืบราชสมบัติให้เป็นไปโดยนัยแห่งกฎมณเฑียรบาลว่าด้วยการสืบราชสันตติวงศ์ พระพุทธศักราช ๒๔๖๗
การแก้ไขเพิ่มเติมกฎมณเฑียรบาลว่าด้วยการสืบราชสันตติวงศ์ พระพุทธศักราช ๒๔๖๗ เป็นพระราชอำนาจของพระมหากษัตริย์โดยเฉพาะ เมื่อมีพระราชดำริประการใด ให้คณะองคมนตรีจัดทำร่างกฎมณเฑียรบาลแก้ไขเพิ่มเติมกฎมณเฑียรบาลเดิมขึ้นทูลเกล้าทูลกระหม่อมถวายเพื่อมีพระราชวินิจฉัย เมื่อทรงเห็นชอบและทรงลงพระปรมาภิไธยแล้ว ให้ประธานองคมนตรีดำเนินการแจ้งประธานรัฐสภาเพื่อให้ประธานรัฐสภาแจ้งให้รัฐสภาทราบ และให้ประธานรัฐสภาลงนามรับสนองพระบรมราชโองการ และเมื่อได้ประกาศในราชกิจจานุเบกษาแล้ว ให้ใช้บังคับเป็นกฎหมายได้', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-21', 'const', '๒๑', 'ในกรณีที่ราชบัลลังก์หากว่างลงและเป็นกรณีที่พระมหากษัตริย์ได้ทรงแต่งตั้งพระรัชทายาทไว้ตามกฎมณเฑียรบาลว่าด้วยการสืบราชสันตติวงศ์ พระพุทธศักราช ๒๔๖๗ แล้ว ให้คณะรัฐมนตรีแจ้งให้ประธานรัฐสภาทราบ และให้ประธานรัฐสภาเรียกประชุมรัฐสภาเพื่อรับทราบและให้ประธานรัฐสภาอัญเชิญองค์พระรัชทายาทขึ้นทรงราชย์เป็นพระมหากษัตริย์สืบไป แล้วให้ประธานรัฐสภาประกาศให้ประชาชนทราบ
ในกรณีที่ราชบัลลังก์หากว่างลงและเป็นกรณีที่พระมหากษัตริย์มิได้ทรงแต่งตั้งพระรัชทายาทไว้ตามวรรคหนึ่ง ให้คณะองคมนตรีเสนอพระนามผู้สืบราชสันตติวงศ์ตามมาตรา ๒๐ ต่อคณะรัฐมนตรีเพื่อเสนอต่อรัฐสภาเพื่อรัฐสภาให้ความเห็นชอบ ในการนี้ จะเสนอพระนามพระราชธิดาก็ได้ เมื่อรัฐสภาให้ความเห็นชอบแล้ว ให้ประธานรัฐสภาอัญเชิญองค์ผู้สืบราชสันตติวงศ์ขึ้นทรงราชย์เป็นพระมหากษัตริย์สืบไปแล้วให้ประธานรัฐสภาประกาศให้ประชาชนทราบ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-22', 'const', '๒๒', 'ในระหว่างที่ยังไม่มีประกาศอัญเชิญองค์พระรัชทายาทหรือองค์ผู้สืบราชสันตติวงศ์ขึ้นทรงราชย์เป็นพระมหากษัตริย์ตามมาตรา ๒๑ ให้ประธานองคมนตรีเป็นผู้สำเร็จราชการแทนพระองค์เป็นการชั่วคราวไปพลางก่อน แต่ในกรณีที่ราชบัลลังก์หากว่างลงในระหว่างที่ได้แต่งตั้งผู้สำเร็จราชการแทนพระองค์ไว้ตามมาตรา ๑๖ หรือมาตรา ๑๗ หรือระหว่างเวลาที่ประธานองคมนตรีเป็นผู้สำเร็จราชการแทนพระองค์ตามมาตรา ๑๘ วรรคหนึ่ง ให้ผู้สำเร็จราชการแทนพระองค์นั้น ๆ แล้วแต่กรณี เป็นผู้สำเร็จราชการแทนพระองค์ต่อไป ทั้งนี้ จนกว่าจะได้ประกาศอัญเชิญองค์พระรัชทายาทหรือองค์ผู้สืบราชสันตติวงศ์ขึ้นทรงราชย์เป็นพระมหากษัตริย์
ในกรณีที่ผู้สำเร็จราชการแทนพระองค์ซึ่งได้รับการแต่งตั้งไว้และเป็นผู้สำเร็จราชการแทนพระองค์ต่อไปตามวรรคหนึ่ง ไม่สามารถปฏิบัติหน้าที่ได้ ให้ประธานองคมนตรีทำหน้าที่ผู้สำเร็จราชการแทนพระองค์เป็นการชั่วคราวไปพลางก่อน
ในกรณีที่ประธานองคมนตรีเป็นผู้สำเร็จราชการแทนพระองค์ตามวรรคหนึ่ง หรือทำหน้าที่ผู้สำเร็จราชการแทนพระองค์เป็นการชั่วคราวตามวรรคสอง ให้นำมาตรา ๑๘ วรรคสาม มาใช้บังคับ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-23', 'const', '๒๓', 'ในกรณีที่คณะองคมนตรีจะต้องปฏิบัติหน้าที่ตามมาตรา ๑๗ หรือมาตรา ๒๑ วรรคสอง หรือประธานองคมนตรีจะต้องเป็นหรือทำหน้าที่ผู้สำเร็จราชการแทนพระองค์ตามมาตรา ๑๘ วรรคหนึ่งหรือวรรคสอง หรือมาตรา ๒๒ วรรคสอง และอยู่ในระหว่างที่ไม่มีประธานองคมนตรี หรือมีแต่ไม่สามารถปฏิบัติหน้าที่ได้ ให้คณะองคมนตรีที่เหลืออยู่เลือกองคมนตรีคนหนึ่งเพื่อทำหน้าที่ประธานองคมนตรี หรือเป็นหรือทำหน้าที่ผู้สำเร็จราชการแทนพระองค์ตามมาตรา ๑๘ วรรคหนึ่งหรือวรรคสอง หรือตามมาตรา ๒๒ วรรคสอง แล้วแต่กรณี', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-24', 'const', '๒๔', 'การถวายสัตย์ปฏิญาณต่อพระมหากษัตริย์ตามรัฐธรรมนูญหรือกฎหมาย พระมหากษัตริย์จะโปรดเกล้าโปรดกระหม่อมให้กระทำต่อพระรัชทายาทซึ่งทรงบรรลุนิติภาวะแล้วหรือต่อผู้แทนพระองค์ก็ได้
ในระหว่างที่ยังมิได้ถวายสัตย์ปฏิญาณตามวรรคหนึ่ง จะโปรดเกล้าโปรดกระหม่อมให้ผู้ซึ่งต้องถวายสัตย์ปฏิญาณปฏิบัติหน้าที่ไปพลางก่อนก็ได้', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๒ พระมหากษัตริย์', FALSE),
  ('const-25', 'const', '๒๕', 'สิทธิและเสรีภาพของปวงชนชาวไทย นอกจากที่บัญญัติคุ้มครองไว้เป็นการเฉพาะในรัฐธรรมนูญแล้ว การใดที่มิได้ห้ามหรือจำกัดไว้ในรัฐธรรมนูญหรือในกฎหมายอื่น บุคคลย่อมมีสิทธิและเสรีภาพที่จะทำการนั้นได้และได้รับความคุ้มครองตามรัฐธรรมนูญ ตราบเท่าที่การใช้สิทธิหรือเสรีภาพเช่นว่านั้นไม่กระทบกระเทือนหรือเป็นอันตรายต่อความมั่นคงของรัฐ ความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน และไม่ละเมิดสิทธิหรือเสรีภาพของบุคคลอื่น
สิทธิหรือเสรีภาพใดที่รัฐธรรมนูญให้เป็นไปตามที่กฎหมายบัญญัติ หรือให้เป็นไปตามหลักเกณฑ์และวิธีการที่กฎหมายบัญญัติ แม้ยังไม่มีการตรากฎหมายนั้นขึ้นใช้บังคับ บุคคลหรือชุมชนย่อมสามารถใช้สิทธิหรือเสรีภาพนั้นได้ตามเจตนารมณ์ของรัฐธรรมนูญ
บุคคลซึ่งถูกละเมิดสิทธิหรือเสรีภาพที่ได้รับความคุ้มครองตามรัฐธรรมนูญ สามารถยกบทบัญญัติแห่งรัฐธรรมนูญเพื่อใช้สิทธิทางศาลหรือยกขึ้นเป็นข้อต่อสู้คดีในศาลได้
บุคคลซึ่งได้รับความเสียหายจากการถูกละเมิดสิทธิหรือเสรีภาพหรือจากการกระทำความผิดอาญาของบุคคลอื่น ย่อมมีสิทธิที่จะได้รับการเยียวยาหรือช่วยเหลือจากรัฐตามที่กฎหมายบัญญัติ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-26', 'const', '๒๖', 'การตรากฎหมายที่มีผลเป็นการจำกัดสิทธิหรือเสรีภาพของบุคคลต้องเป็นไปตามเงื่อนไขที่บัญญัติไว้ในรัฐธรรมนูญ ในกรณีที่รัฐธรรมนูญมิได้บัญญัติเงื่อนไขไว้ กฎหมายดังกล่าวต้องไม่ขัดต่อหลักนิติธรรม ไม่เพิ่มภาระหรือจำกัดสิทธิหรือเสรีภาพของบุคคลเกินสมควรแก่เหตุ และจะกระทบต่อศักดิ์ศรีความเป็นมนุษย์ของบุคคลมิได้ รวมทั้งต้องระบุเหตุผลความจำเป็นในการจำกัดสิทธิและเสรีภาพไว้ด้วย
กฎหมายตามวรรคหนึ่ง ต้องมีผลใช้บังคับเป็นการทั่วไป ไม่มุ่งหมายให้ใช้บังคับแก่กรณีใดกรณีหนึ่งหรือแก่บุคคลใดบุคคลหนึ่งเป็นการเจาะจง', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-27', 'const', '๒๗', 'บุคคลย่อมเสมอกันในกฎหมาย มีสิทธิและเสรีภาพและได้รับความคุ้มครองตามกฎหมายเท่าเทียมกัน
ชายและหญิงมีสิทธิเท่าเทียมกัน
การเลือกปฏิบัติโดยไม่เป็นธรรมต่อบุคคล ไม่ว่าด้วยเหตุความแตกต่างในเรื่องถิ่นกำเนิด เชื้อชาติ ภาษา เพศ อายุ ความพิการ สภาพทางกายหรือสุขภาพ สถานะของบุคคล ฐานะทางเศรษฐกิจหรือสังคม ความเชื่อทางศาสนา การศึกษาอบรม หรือความคิดเห็นทางการเมืองอันไม่ขัดต่อบทบัญญัติแห่งรัฐธรรมนูญ หรือเหตุอื่นใด จะกระทำมิได้
มาตรการที่รัฐกำหนดขึ้นเพื่อขจัดอุปสรรคหรือส่งเสริมให้บุคคลสามารถใช้สิทธิหรือเสรีภาพได้เช่นเดียวกับบุคคลอื่น หรือเพื่อคุ้มครองหรืออำนวยความสะดวกให้แก่เด็ก สตรี ผู้สูงอายุ คนพิการ หรือผู้ด้อยโอกาส ย่อมไม่ถือว่าเป็นการเลือกปฏิบัติโดยไม่เป็นธรรมตามวรรคสาม
บุคคลผู้เป็นทหาร ตำรวจ ข้าราชการ เจ้าหน้าที่อื่นของรัฐ และพนักงานหรือลูกจ้างขององค์กรของรัฐย่อมมีสิทธิและเสรีภาพเช่นเดียวกับบุคคลทั่วไป เว้นแต่ที่จำกัดไว้ในกฎหมายเฉพาะในส่วนที่เกี่ยวกับการเมือง สมรรถภาพ วินัย หรือจริยธรรม', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-28', 'const', '๒๘', 'บุคคลย่อมมีสิทธิและเสรีภาพในชีวิตและร่างกาย
การจับและการคุมขังบุคคลจะกระทำมิได้ เว้นแต่มีคำสั่งหรือหมายของศาลหรือมีเหตุอย่างอื่นตามที่กฎหมายบัญญัติ
การค้นตัวบุคคลหรือการกระทำใดอันกระทบกระเทือนต่อสิทธิหรือเสรีภาพในชีวิตหรือร่างกายจะกระทำมิได้ เว้นแต่มีเหตุตามที่กฎหมายบัญญัติ
การทรมาน ทารุณกรรม หรือการลงโทษด้วยวิธีการโหดร้ายหรือไร้มนุษยธรรมจะกระทำมิได้', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-29', 'const', '๒๙', 'บุคคลไม่ต้องรับโทษอาญา เว้นแต่ได้กระทำการอันกฎหมายที่ใช้อยู่ในเวลาที่กระทำนั้นบัญญัติเป็นความผิดและกำหนดโทษไว้ และโทษที่จะลงแก่บุคคลนั้นจะหนักกว่าโทษที่บัญญัติไว้ในกฎหมายที่ใช้อยู่ในเวลาที่กระทำความผิดมิได้
ในคดีอาญา ให้สันนิษฐานไว้ก่อนว่าผู้ต้องหาหรือจำเลยไม่มีความผิด และก่อนมีคำพิพากษาอันถึงที่สุดแสดงว่าบุคคลใดได้กระทำความผิด จะปฏิบัติต่อบุคคลนั้นเสมือนเป็นผู้กระทำความผิดมิได้
การควบคุมหรือคุมขังผู้ต้องหาหรือจำเลยให้กระทำได้เพียงเท่าที่จำเป็น เพื่อป้องกันมิให้มีการหลบหนี
ในคดีอาญา จะบังคับให้บุคคลให้การเป็นปฏิปักษ์ต่อตนเองมิได้
คำขอประกันผู้ต้องหาหรือจำเลยในคดีอาญาต้องได้รับการพิจารณาและจะเรียกหลักประกันจนเกินควรแก่กรณีมิได้ การไม่ให้ประกันต้องเป็นไปตามที่กฎหมายบัญญัติ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-30', 'const', '๓๐', 'การเกณฑ์แรงงานจะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเพื่อป้องกันภัยพิบัติสาธารณะ หรือในขณะที่มีการประกาศสถานการณ์ฉุกเฉินหรือประกาศใช้กฎอัยการศึก หรือในระหว่างเวลาที่ประเทศอยู่ในภาวะสงครามหรือการรบ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-31', 'const', '๓๑', 'บุคคลย่อมมีเสรีภาพบริบูรณ์ในการถือศาสนาและย่อมมีเสรีภาพในการปฏิบัติหรือประกอบพิธีกรรมตามหลักศาสนาของตน แต่ต้องไม่เป็นปฏิปักษ์ต่อหน้าที่ของปวงชนชาวไทย ไม่เป็นอันตรายต่อความปลอดภัยของรัฐ และไม่ขัดต่อความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-32', 'const', '๓๒', 'บุคคลย่อมมีสิทธิในความเป็นอยู่ส่วนตัว เกียรติยศ ชื่อเสียง และครอบครัว
การกระทำอันเป็นการละเมิดหรือกระทบต่อสิทธิของบุคคลตามวรรคหนึ่ง หรือการนำข้อมูลส่วนบุคคลไปใช้ประโยชน์ไม่ว่าในทางใด ๆ จะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเพียงเท่าที่จำเป็นเพื่อประโยชน์สาธารณะ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-33', 'const', '๓๓', 'บุคคลย่อมมีเสรีภาพในเคหสถาน
การเข้าไปในเคหสถานโดยปราศจากความยินยอมของผู้ครอบครอง หรือการค้นเคหสถานหรือที่รโหฐานจะกระทำมิได้ เว้นแต่มีคำสั่งหรือหมายของศาลหรือมีเหตุอย่างอื่นตามที่กฎหมายบัญญัติ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-34', 'const', '๓๔', 'บุคคลย่อมมีเสรีภาพในการแสดงความคิดเห็น การพูด การเขียน การพิมพ์ การโฆษณา และการสื่อความหมายโดยวิธีอื่น การจำกัดเสรีภาพดังกล่าวจะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเฉพาะเพื่อรักษาความมั่นคงของรัฐ เพื่อคุ้มครองสิทธิหรือเสรีภาพของบุคคลอื่น เพื่อรักษาความสงบเรียบร้อยหรือศีลธรรมอันดีของประชาชน หรือเพื่อป้องกันสุขภาพของประชาชน
เสรีภาพทางวิชาการย่อมได้รับความคุ้มครอง แต่การใช้เสรีภาพนั้นต้องไม่ขัดต่อหน้าที่ของปวงชนชาวไทยหรือศีลธรรมอันดีของประชาชน และต้องเคารพและไม่ปิดกั้นความเห็นต่างของบุคคลอื่น', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-35', 'const', '๓๕', 'บุคคลซึ่งประกอบวิชาชีพสื่อมวลชนย่อมมีเสรีภาพในการเสนอข่าวสารหรือการแสดงความคิดเห็นตามจริยธรรมแห่งวิชาชีพ
การสั่งปิดกิจการหนังสือพิมพ์หรือสื่อมวลชนอื่นเพื่อลิดรอนเสรีภาพตามวรรคหนึ่ง จะกระทำมิได้
การให้นำข่าวสารหรือข้อความใด ๆ ที่ผู้ประกอบวิชาชีพสื่อมวลชนจัดทำขึ้นไปให้เจ้าหน้าที่ตรวจก่อนนำไปโฆษณาในหนังสือพิมพ์หรือสื่อใด ๆ จะกระทำมิได้ เว้นแต่จะกระทำในระหว่างเวลาที่ประเทศอยู่ในภาวะสงคราม
เจ้าของกิจการหนังสือพิมพ์หรือสื่อมวลชนอื่นต้องเป็นบุคคลสัญชาติไทย
การให้เงินหรือทรัพย์สินอื่นเพื่ออุดหนุนกิจการหนังสือพิมพ์หรือสื่อมวลชนอื่นของเอกชนรัฐจะกระทำมิได้ หน่วยงานของรัฐที่ใช้จ่ายเงินหรือทรัพย์สินให้สื่อมวลชนไม่ว่าเพื่อประโยชน์ในการโฆษณาหรือประชาสัมพันธ์ หรือเพื่อการอื่นใดในทำนองเดียวกันต้องเปิดเผยรายละเอียดให้คณะกรรมการตรวจเงินแผ่นดินทราบตามระยะเวลาที่กำหนดและประกาศให้ประชาชนทราบด้วย
เจ้าหน้าที่ของรัฐซึ่งปฏิบัติหน้าที่สื่อมวลชนย่อมมีเสรีภาพตามวรรคหนึ่ง แต่ให้คำนึงถึงวัตถุประสงค์และภารกิจของหน่วยงานที่ตนสังกัดอยู่ด้วย', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-36', 'const', '๓๖', 'บุคคลย่อมมีเสรีภาพในการติดต่อสื่อสารถึงกันไม่ว่าในทางใด ๆ
การตรวจ การกัก หรือการเปิดเผยข้อมูลที่บุคคลสื่อสารถึงกัน รวมทั้งการกระทำด้วยประการใด ๆ เพื่อให้ล่วงรู้หรือได้มาซึ่งข้อมูลที่บุคคลสื่อสารถึงกันจะกระทำมิได้ เว้นแต่มีคำสั่งหรือหมายของศาลหรือมีเหตุอย่างอื่นตามที่กฎหมายบัญญัติ', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-37', 'const', '๓๗', 'บุคคลย่อมมีสิทธิในทรัพย์สินและการสืบมรดก
ขอบเขตแห่งสิทธิและการจำกัดสิทธิเช่นว่านี้ ให้เป็นไปตามที่กฎหมายบัญญัติ
การเวนคืนอสังหาริมทรัพย์จะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเพื่อการอันเป็นสาธารณูปโภค การป้องกันประเทศ หรือการได้มาซึ่งทรัพยากรธรรมชาติ หรือเพื่อประโยชน์สาธารณะอย่างอื่น และต้องชดใช้ค่าทดแทนที่เป็นธรรม ภายในเวลาอันควรแก่เจ้าของตลอดจนผู้ทรงสิทธิบรรดาที่ได้รับความเสียหายจากการเวนคืน โดยคำนึงถึงประโยชน์สาธารณะผลกระทบต่อผู้ถูกเวนคืน รวมทั้งประโยชน์ที่ผู้ถูกเวนคืนอาจได้รับจากการเวนคืนนั้น
การเวนคืนอสังหาริมทรัพย์ ให้กระทำเพียงเท่าที่จำเป็นต้องใช้เพื่อการที่บัญญัติไว้ในวรรคสาม เว้นแต่เป็นการเวนคืนเพื่อนำอสังหาริมทรัพย์ที่เวนคืนไปชดเชยให้เกิดความเป็นธรรมแก่เจ้าของอสังหาริมทรัพย์ที่ถูกเวนคืนตามที่กฎหมายบัญญัติ
กฎหมายเวนคืนอสังหาริมทรัพย์ต้องระบุวัตถุประสงค์แห่งการเวนคืนและกำหนดระยะเวลาการเข้าใช้อสังหาริมทรัพย์ให้ชัดแจ้ง ถ้ามิได้ใช้ประโยชน์เพื่อการนั้นภายในระยะเวลาที่กำหนดหรือมีอสังหาริมทรัพย์เหลือจากการใช้ประโยชน์ และเจ้าของเดิมหรือทายาทประสงค์จะได้คืน ให้คืนแก่เจ้าของเดิมหรือทายาท
ระยะเวลาการขอคืนและการคืนอสังหาริมทรัพย์ที่ถูกเวนคืนที่มิได้ใช้ประโยชน์ หรือที่เหลือจากการใช้ประโยชน์ให้แก่เจ้าของเดิมหรือทายาท และการเรียกคืนค่าทดแทนที่ชดใช้ไป ให้เป็นไปตามที่กฎหมายบัญญัติ
การตรากฎหมายเวนคืนอสังหาริมทรัพย์โดยระบุเจาะจงอสังหาริมทรัพย์หรือเจ้าของอสังหาริมทรัพย์ที่ถูกเวนคืนตามความจำเป็น มิให้ถือว่าเป็นการขัดต่อมาตรา ๒๖ วรรคสอง', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-38', 'const', '๓๘', 'บุคคลย่อมมีเสรีภาพในการเดินทางและการเลือกถิ่นที่อยู่
การจำกัดเสรีภาพตามวรรคหนึ่งจะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเพื่อความมั่นคงของรัฐ ความสงบเรียบร้อยหรือสวัสดิภาพของประชาชน หรือการผังเมือง หรือเพื่อรักษาสถานภาพของครอบครัว หรือเพื่อสวัสดิภาพของผู้เยาว์', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-39', 'const', '๓๙', 'การเนรเทศบุคคลสัญชาติไทยออกนอกราชอาณาจักร หรือห้ามมิให้ผู้มีสัญชาติไทยเข้ามาในราชอาณาจักร จะกระทำมิได้
การถอนสัญชาติของบุคคลซึ่งมีสัญชาติไทยโดยการเกิด จะกระทำมิได้', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-40', 'const', '๔๐', 'บุคคลย่อมมีเสรีภาพในการประกอบอาชีพ
การจำกัดเสรีภาพตามวรรคหนึ่งจะกระทำมิได้ เว้นแต่โดยอาศัยอำนาจตามบทบัญญัติแห่งกฎหมายที่ตราขึ้นเพื่อรักษาความมั่นคงหรือเศรษฐกิจของประเทศ การแข่งขันอย่างเป็นธรรม การป้องกันหรือขจัดการกีดกันหรือการผูกขาด การคุ้มครองผู้บริโภค การจัดระเบียบการประกอบอาชีพเพียงเท่าที่จำเป็น หรือเพื่อประโยชน์สาธารณะอย่างอื่น
การตรากฎหมายเพื่อจัดระเบียบการประกอบอาชีพตามวรรคสอง ต้องไม่มีลักษณะเป็นการเลือกปฏิบัติหรือก้าวก่ายการจัดการศึกษาของสถาบันการศึกษา', 'รัฐธรรมนูญแห่งราชอาณาจักรไทย > หมวด ๓ สิทธิและเสรีภาพของปวงชนชาวไทย', FALSE),
  ('const-41', 'const', '๔๑', 'บุคคลและชุมชนย่อมมีสิทธิ
